LOCK TABLES `concession_item` WRITE;
/*!40000 ALTER TABLE `concession_item` DISABLE KEYS */;
INSERT INTO `concession_item` VALUES (1,'cb-big-1','Combo Big 1 – Pepsi L + Bắp L','Gồm: 1 Pepsi size L, 1 bắp rang bơ size L. Combo kinh điển cho 1 người thích uống nhiều.',85000.00,105000.00,'BEST VALUE','/assets/images/concessions/combo/cb-big-1.jpg',1,'combo'),(2,'cb-big-2','Combo Big 2 – 2 Pepsi L + 1 Bắp L','Tiết kiệm cho 2 người: 2 Pepsi size L, 1 bắp rang size L.',125000.00,150000.00,'HOT','/assets/images/concessions/combo/cb-big-2.jpg',1,'combo'),(3,'cb-family','Family Combo – 4 Pepsi L + 1 Bắp XL + 1 Pizza XL','Combo đại gia đình: 4 Pepsi size L, bắp rang size XL, pizza size XL.',259000.00,299000.00,'BEST DEAL','/assets/images/concessions/combo/cb-family.png',1,'combo'),(4,'cb-friends-1','Friends Combo 1 – 3 Pepsi L + 1 Bắp L + 1 Snack','Phù hợp nhóm 3: 3 Pepsi size L, bắp rang L, kèm snack.',145000.00,169000.00,NULL,'/assets/images/concessions/combo/cb-friends-1.jpg',1,'combo'),(5,'cb-friends-2','Friends Combo 2 – 4 Pepsi L + 2 Bắp L + 2 Snack','Combo nhóm 4 cực tiết kiệm: 4 nước L, 2 bắp L, 2 snack.',189000.00,219000.00,'HOT','/assets/images/concessions/combo/cb-friends-2.jpg',1,'combo'),(6,'cb-capybara','Capybara Gift Combo','1 Pepsi size L, 1 bắp rang L và bộ quà tặng Capybara siêu dễ thương.',99000.00,129000.00,'LIMITED','/assets/images/concessions/combo/cb-capybara.jpg',1,'combo'),(7,'cb-jujutsu-kaisen','Jujutsu Kaisen Gift Combo','1 Pepsi L + 1 bắp L + bộ quà tặng Jujutsu Kaisen ngẫu nhiên.',109000.00,139000.00,'LIMITED','/assets/images/concessions/combo/cb-jujutsu-kaisen.jpg',1,'combo'),(8,'cb-zootopia-ii','Zootopia II Special Combo','1 Pepsi L + 1 bắp L + 2 ly chủ đề phim Zootopia 2.',119000.00,149000.00,'LIMITED','/assets/images/concessions/combo/cb-zootopia-ii.jpg',1,'combo'),(9,'pc-caramel','Bắp Caramel L','Bắp rang vị caramel thơm ngọt.',45000.00,55000.00,NULL,'/assets/images/concessions/popcorn/pc-caramel.jpg',1,'popcorn'),(10,'pc-cheese','Bắp Phô Mai L','Bắp rang phủ phô mai mặn mà, thơm béo.',45000.00,55000.00,NULL,'/assets/images/concessions/popcorn/pc-cheese.jpg',1,'popcorn'),(11,'pc-original','Bắp Truyền Thống L','Bắp rang bơ truyền thống, giòn thơm.',40000.00,50000.00,NULL,'/assets/images/concessions/popcorn/pc-original.jpg',1,'popcorn'),(12,'pc-matcha','Bắp Matcha L','Bắp rang vị matcha nhẹ nhàng, thơm lạ miệng.',49000.00,59000.00,NULL,'/assets/images/concessions/popcorn/pc-matcha.jpg',1,'popcorn'),(13,'br-coca','Coca-Cola (L)','Nước giải khát Coca-Cola size L.',35000.00,NULL,NULL,'/assets/images/concessions/baverage/br-coca.webp',1,'beverage'),(14,'br-pepsi','Pepsi (L)','Pepsi size L – lựa chọn phổ biến nhất.',35000.00,NULL,NULL,'/assets/images/concessions/baverage/br-pepsi.png',1,'beverage'),(15,'br-7up','7Up (L)','7Up size L – mát lạnh, giải nhiệt.',35000.00,NULL,NULL,'/assets/images/concessions/baverage/br-7up.png',1,'beverage'),(16,'br-mirinda-cam','Mirinda Cam (L)','Nước Mirinda hương cam size L.',35000.00,NULL,NULL,'/assets/images/concessions/baverage/br-mirinda-cam.png',1,'beverage'),(17,'br-milktea','Okinawa Milk Foam Smoothie (M)','Okinawa Kem Sữa Đá Xay là một thức uống giải khát độc đáo và hấp dẫn, nổi tiếng với sự kết hợp hài hòa giữa vị béo ngậy và ngọt thanh.',60000.00,NULL,NULL,'/assets/images/concessions/baverage/br-milktea.png',1,'beverage'),(18,'br-sjora','Sjora Vị Xoài Đào (L)','SJORA Xoài Đào là một loại nước giải khát có sữa, nổi tiếng với hương vị trái cây nhiệt đới tươi mát và độc đáo. Là sự kết hợp hài hòa của hương vị xoài và đào tự nhiên, tạo cảm giác sảng khoái, giải nhiệt.',40000.00,NULL,NULL,'/assets/images/concessions/baverage/br-sjora.png',1,'beverage'),(19,'br-lychee-tea','Trà Vải (L)','Trà vải thanh mát, hương vị trà nguyên chất, đậm đà và ngọt ngào.',42000.00,NULL,NULL,'/assets/images/concessions/baverage/br-lychee-tea.png',1,'beverage'),(20,'br-lipton','Lipton Chanh (L)','Lipton đá chanh size L.',35000.00,NULL,NULL,'/assets/images/concessions/baverage/br-lipton.png',1,'beverage'),(21,'br-kiwi-soda','Kiwi Soda','Soda vị kiwi mát lạnh.',42000.00,NULL,NULL,'/assets/images/concessions/baverage/br-kiwi-soda.jpg',1,'beverage'),(22,'br-atiso-soda','Atiso Soda','Soda vị atiso tốt cho sức khỏe.',42000.00,NULL,NULL,'/assets/images/concessions/baverage/br-atiso-soda.jpg',1,'beverage'),(23,'br-melon-soda','Melon Soda','Soda vị dưa lưới.',42000.00,NULL,NULL,'/assets/images/concessions/baverage/br-melon-soda.jpg',1,'beverage'),(24,'br-aquafina','Aquafina','Nước suối Aquafina.',20000.00,NULL,NULL,'/assets/images/concessions/baverage/br-aquafina.png',1,'beverage'),(25,'hf-hot-dog','Hotdog','Xúc xích nóng kèm bánh mềm.',35000.00,NULL,NULL,'/assets/images/concessions/hotfood/hf-hot-dog.jpg',1,'hot-food'),(26,'hf-mandu','Mandu Chiên','Bánh mandu nhân thịt chiên giòn.',39000.00,NULL,NULL,'/assets/images/concessions/hotfood/hf-mandu.jpg',1,'hot-food'),(27,'hf-toppoki','Tokbokki','Bánh gạo sốt cay Hàn Quốc.',45000.00,NULL,NULL,'/assets/images/concessions/hotfood/hf-toppoki.jpg',1,'hot-food'),(28,'hf-pizza','Pizza Slice','1 lát pizza nóng giòn.',49000.00,NULL,NULL,'/assets/images/concessions/hotfood/hf-pizza.jpg',1,'hot-food'),(29,'hf-nugget','Gà Nugget','Gà nugget chiên giòn.',39000.00,NULL,NULL,'/assets/images/concessions/hotfood/hf-nugget.jpg',1,'hot-food'),(30,'cf-milk','Sữa Tươi','Ly sữa tươi mát lạnh.',30000.00,NULL,NULL,'/assets/images/concessions/coffee/cf-milk.jpg',1,'coffee'),(31,'cf-americano','Americano','Cà phê Americano đậm vị.',39000.00,NULL,NULL,'/assets/images/concessions/coffee/cf-americano.jpg',1,'coffee'),(32,'cf-cappuccino','Cappuccino','Cappuccino béo nhẹ, thơm.',45000.00,NULL,NULL,'/assets/images/concessions/coffee/cf-cappuccino.jpg',1,'coffee'),(33,'cf-mocha','Mocha','Cà phê mocha đậm ngọt.',45000.00,NULL,NULL,'/assets/images/concessions/coffee/cf-mocha.jpg',1,'coffee'),(34,'ds-cream-puff','Bánh Su Kem','Bánh su kem béo ngọt.',25000.00,NULL,NULL,'/assets/images/concessions/dessert/ds-cream-puff.jpg',1,'dessert'),(35,'ds-chocolate','Chocolate Bar','Thanh chocolate cacao thơm đậm.',30000.00,NULL,NULL,'/assets/images/concessions/dessert/ds-chocolate.jpg',1,'dessert'),(36,'ds-candy','Kẹo Mix','Hỗn hợp kẹo đủ vị.',20000.00,NULL,NULL,'/assets/images/concessions/dessert/ds-candy.jpg',1,'dessert'),(37,'ds-nabati','Nabati','Bánh xốp Nabati truyền thống.',15000.00,NULL,NULL,'/assets/images/concessions/dessert/ds-nabati.jpg',1,'dessert'),(38,'ds-yogurt','Yogurt Trái Cây','Sữa chua trái cây.',25000.00,NULL,NULL,'/assets/images/concessions/dessert/ds-yogurt.jpg',1,'dessert');
